<script setup lang="ts">
import {computed} from 'vue';
import {palettes} from '../charts/config';
import type {ChartSettings} from '../state/project';
const props=defineProps<{settings:ChartSettings;headers:string[];columnIds?:string[];combo:boolean}>();
const emit=defineEmits<{change:[value:Partial<ChartSettings>]}>();
const columns=computed(()=>props.headers.slice(1).map((header,index)=>({column:index+1,id:props.columnIds?.[index+1]??String(index+1),header})));
const ordered=computed(()=>{const byId=new Map(columns.value.map(item=>[item.id,item])),order=(props.settings.seriesOrder??[]).map(String).filter(id=>byId.has(id));for(const item of columns.value)if(!order.includes(item.id))order.push(item.id);return order.map(id=>byId.get(id)!);});
function hasRef(source:(number|string)[]|null|undefined,item:{column:number;id:string}){return(source??[]).some(ref=>String(ref)===item.id||ref===item.column);}
const rightColumns=computed(()=>props.settings.comboRightAxisColumns??columns.value.filter(item=>!hasRef(props.settings.comboBarColumns,item)).map(item=>item.id));
function valueOf<T>(source:Record<string,T>,item:{column:number;id:string}){return source[item.id]??source[String(item.column)];}
function patchMap<T>(source:Record<string,T>,id:string,value:T,key:keyof ChartSettings){emit('change',{[key]:{...source,[id]:value}} as Partial<ChartSettings>);}
function move(index:number,direction:number){const order=ordered.value.map(item=>item.id),target=index+direction;if(target<0||target>=order.length)return;[order[index],order[target]]=[order[target],order[index]];emit('change',{seriesOrder:order});}
function toggleList(source:(number|string)[],id:string,enabled:boolean,key:keyof ChartSettings){const next=new Set(source.map(String));enabled?next.add(id):next.delete(id);emit('change',{[key]:[...next]} as Partial<ChartSettings>);}
function toggleVisible(item:{column:number;id:string},visible:boolean){const next=new Set(props.settings.hiddenColumns.map(String));visible?next.delete(item.id):next.add(item.id);if(next.size>=columns.value.length)return;emit('change',{hiddenColumns:[...next]});}
function color(item:{column:number;id:string}){return props.settings.seriesColors?.[item.id]??props.settings.customColors[item.column-1]??palettes[props.settings.theme].colors[(item.column-1)%palettes[props.settings.theme].colors.length];}
function setPointStyle(id:string,value:string){patchMap(props.settings.seriesPointStyles,id,value as ChartSettings['seriesPointStyles'][string],'seriesPointStyles');}
function setTrendline(id:string,value:string){patchMap(props.settings.seriesTrendlines,id,value as ChartSettings['seriesTrendlines'][string],'seriesTrendlines');}
function setColor(item:{column:number;id:string},value:string){emit('change',{seriesColors:{...(props.settings.seriesColors??{}),[item.id]:value}});}
</script>
<template><section class="property-section series-editor"><label>数据系列</label><div v-if="settings.type==='line'||settings.type==='area'||combo" class="trend-options"><label>显示公式<input type="checkbox" :checked="settings.showTrendEquation" @change="emit('change',{showTrendEquation:($event.target as HTMLInputElement).checked})"></label><label>显示 R²<input type="checkbox" :checked="settings.showTrendR2" @change="emit('change',{showTrendR2:($event.target as HTMLInputElement).checked})"></label></div><article v-for="(item,index) in ordered" :key="item.id" class="series-card"><header><input type="color" :value="color(item)" @input="setColor(item,($event.target as HTMLInputElement).value)"><input class="series-title" :value="valueOf(settings.seriesNames,item)??item.header" @change="patchMap(settings.seriesNames,item.id,($event.target as HTMLInputElement).value.trim(),'seriesNames')"><button title="上移" :disabled="index===0" @click="move(index,-1)">↑</button><button title="下移" :disabled="index===ordered.length-1" @click="move(index,1)">↓</button><input type="checkbox" title="显示系列" :checked="!hasRef(settings.hiddenColumns,item)" @change="toggleVisible(item,($event.target as HTMLInputElement).checked)"></header><div v-if="combo" class="series-options"><select :value="hasRef(settings.comboBarColumns,item)?'bar':'line'" @change="toggleList(settings.comboBarColumns,item.id,($event.target as HTMLSelectElement).value==='bar','comboBarColumns')"><option value="bar">柱状</option><option value="line">折线</option></select><select :value="rightColumns.map(String).includes(item.id)?'right':'left'" @change="toggleList(rightColumns,item.id,($event.target as HTMLSelectElement).value==='right','comboRightAxisColumns')"><option value="left">左轴</option><option value="right">右轴</option></select></div><label>透明度 {{Math.round((valueOf(settings.seriesOpacity,item)??1)*100)}}%</label><input type="range" min="0.15" max="1" step="0.05" :value="valueOf(settings.seriesOpacity,item)??1" @input="patchMap(settings.seriesOpacity,item.id,Number(($event.target as HTMLInputElement).value),'seriesOpacity')"><template v-if="settings.type==='line'||settings.type==='area'||(combo&&!hasRef(settings.comboBarColumns,item))"><div class="series-inline"><label>线宽<input type="number" min="1" max="8" :value="valueOf(settings.seriesLineWidths,item)??settings.lineWidth" @change="patchMap(settings.seriesLineWidths,item.id,Number(($event.target as HTMLInputElement).value),'seriesLineWidths')"></label><label>点大小<input type="number" min="0" max="10" :value="valueOf(settings.seriesPointRadii,item)??settings.pointRadius" @change="patchMap(settings.seriesPointRadii,item.id,Number(($event.target as HTMLInputElement).value),'seriesPointRadii')"></label><label class="series-check">虚线<input type="checkbox" :checked="valueOf(settings.seriesDashed,item)??settings.lineDash" @change="patchMap(settings.seriesDashed,item.id,($event.target as HTMLInputElement).checked,'seriesDashed')"></label></div><div class="series-trend"><label>点型<select :value="valueOf(settings.seriesPointStyles,item)??'circle'" @change="setPointStyle(item.id,($event.target as HTMLSelectElement).value)"><option value="circle">圆形</option><option value="rect">方形</option><option value="triangle">三角</option><option value="rectRot">菱形</option><option value="cross">十字</option></select></label><label>趋势线<select :value="valueOf(settings.seriesTrendlines,item)??'none'" @change="setTrendline(item.id,($event.target as HTMLSelectElement).value)"><option value="none">无</option><option value="linear">线性</option><option value="polynomial">二次多项式</option><option value="movingAverage">移动平均</option></select></label><label v-if="valueOf(settings.seriesTrendlines,item)==='movingAverage'">周期<input type="number" min="2" max="20" :value="valueOf(settings.seriesMovingAveragePeriods,item)??3" @change="patchMap(settings.seriesMovingAveragePeriods,item.id,Number(($event.target as HTMLInputElement).value),'seriesMovingAveragePeriods')"></label></div></template></article></section></template>
